import { test } from 'node:test';
import net from 'node:net';
import { boot, request, valid } from '../../test/helpers/server-harness.mjs';

function raw(port, data) {
  return new Promise((resolve) => {
    const s = net.connect(port, '127.0.0.1', () => s.end(data));
    const chunks = [];
    s.on('data', (c) => chunks.push(c));
    s.on('error', (e) => resolve(`ERR ${e.code} after ${Buffer.concat(chunks).toString()}`));
    s.on('close', () => resolve(Buffer.concat(chunks).toString()));
  });
}

